def test_produce_at_exactly_ten_thousand_lb_requires_seal():
    result = evaluate_seal_requirement_check(
        make_check(commodity="produce", weight_lb=Decimal("10000"))
    )
    assert result.required is True
    assert result.reason_code == "produce_food_safety"


def test_produce_just_below_ten_thousand_lb_is_exempt():
    result = evaluate_seal_requirement_check(
        make_check(commodity="produce", weight_lb=Decimal("9999.99"))
    )
    assert result.required is False
    assert result.reason_code == "produce_below_threshold"


