bol_reference_parser.py:
"""Normalize bill-of-lading references from raw strings.

The settlement pipeline receives reference strings copied from shipper paperwork and EDI.
This parser extracts stable reference components so matching can ignore punctuation,
spacing, repeated labels, and scanner noise. Business rules:

- Empty tokens and tokens with no letters or digits are ignored.
- Known labels map to canonical prefixes: ``BOL``, ``PO``, ``SO``, and ``PU``.
- A token like ``BOL12345`` or ``PO-7788`` becomes one prefixed reference when the
  prefix is recognized and the remainder is valid.
- Numeric payloads drop leading zeros unless the whole value is zero. Alphanumeric
  payloads keep internal zeros.
- Payloads shorter than 3 characters are ignored, except ``PO`` allows 1 and ``PU``
  allows 1 because some customers use short order and pickup numbers.
- Payloads longer than 12 characters are ignored unless they are all digits, in which
  case the last 12 digits are kept; this handles overflowed scans.
- Duplicate normalized references are suppressed in first-seen order.
- A bare token with no recognizable prefix is treated as ``BOL`` only when it is all
  digits and has normalized length 3 to 10 inclusive.
"""

from dataclasses import dataclass

LABELS = {
    "BOL": "BOL",
    "BILL": "BOL",
    "BILL OF LADING": "BOL",
    "BILL-OF-LADING": "BOL",
    "PO": "PO",
    "P/O": "PO",
    "PURCHASE ORDER": "PO",
    "SO": "SO",
    "SHIPPER ORDER": "SO",
    "PU": "PU",
    "PICKUP": "PU",
}
MIN_LEN = {"BOL": 3, "PO": 1, "SO": 3, "PU": 1}
MAX_LEN = 12
SEPARATORS = " :-#/\\"


@dataclass(frozen=True)
class RawReferenceSet:
    references: tuple[str, ...]


@dataclass(frozen=True)
class ParsedReference:
    prefix: str
    value: str


def _clean(text: str) -> str:
    return " ".join(text.strip().upper().split())


def _payload_chars(text: str) -> str:
    return "".join(ch for ch in text if ch.isalnum())


def _normalize_value(prefix: str, value: str) -> str | None:
    raw = _payload_chars(value)
    if not raw:
        return None
    if raw.isdigit():
        raw = raw.lstrip("0") or "0"
    if len(raw) > MAX_LEN:
        if raw.isdigit():
            raw = raw[-MAX_LEN:]
        else:
            return None
    if len(raw) < MIN_LEN[prefix]:
        return None
    return raw


def _split_prefixed_token(token: str) -> tuple[str, str] | None:
    compact = _clean(token)
    for label, prefix in sorted(LABELS.items(), key=lambda item: len(item[0]), reverse=True):
        if compact == label:
            return None
        if compact.startswith(label):
            remainder = compact[len(label):].lstrip(SEPARATORS)
            if remainder:
                return prefix, remainder
    return None


def _extract_one(token: str, pending_prefix: str | None) -> tuple[ParsedReference | None, str | None]:
    cleaned = _clean(token)
    if not cleaned:
        return None, pending_prefix
    if cleaned in LABELS:
        return None, LABELS[cleaned]
    combined = _split_prefixed_token(cleaned)
    if combined is not None:
        prefix, remainder = combined
        value = _normalize_value(prefix, remainder)
        return (ParsedReference(prefix, value) if value else None), None
    if pending_prefix is not None:
        value = _normalize_value(pending_prefix, cleaned)
        return (ParsedReference(pending_prefix, value) if value else None), None
    raw = _payload_chars(cleaned)
    if raw.isdigit():
        normalized = raw.lstrip("0") or "0"
        if 3 <= len(normalized) <= 10:
            return ParsedReference("BOL", normalized), None
    return None, None


def parse_bol_references(raw: RawReferenceSet) -> tuple[ParsedReference, ...]:
    """Return unique normalized reference components in first-seen order."""
    seen: set[tuple[str, str]] = set()
    parsed: list[ParsedReference] = []
    pending_prefix: str | None = None
    for token in raw.references:
        item, pending_prefix = _extract_one(token, pending_prefix)
        if item is None:
            continue
        key = (item.prefix, item.value)
        if key in seen:
            continue
        seen.add(key)
        parsed.append(item)
    return tuple(parsed)

mode_conversion_factor.py:
"""Equivalent rating factors for converting between freight pricing modes.

Operations normalizes customer rates across truckload, LTL, drayage, and flatbed so
analytics can compare bids on a common basis. The conversion here returns a factor
that multiplies the source mode's amount into an equivalent target-mode amount.

Business rules:
- Base factors are configured per source/target mode pair.
- Weight, distance, and stop count slightly adjust the factor within narrow bands.
- Residential delivery only affects LTL destinations.
- Hazmat applies a small uplift except on drayage, where local port tariffs already
  include most handling.
- Cross-border moves add friction on truckload and flatbed conversions.
- Very short drayage moves under 25 miles use a local minimum factor.
- Flatbed with over-dimensional freight adds an extra uplift.
- Final factors are rounded half up to four decimals and never below 0.2500.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

FOUR_PLACES = Decimal("0.0001")
MIN_FACTOR = Decimal("0.2500")

_BASE_FACTORS = {
    ("truckload", "ltl"): Decimal("1.1800"),
    ("truckload", "drayage"): Decimal("0.7601"),
    ("truckload", "flatbed"): Decimal("1.1200"),
    ("ltl", "truckload"): Decimal("0.8500"),
    ("ltl", "drayage"): Decimal("0.6400"),
    ("ltl", "flatbed"): Decimal("1.0500"),
    ("drayage", "truckload"): Decimal("1.3100"),
    ("drayage", "ltl"): Decimal("1.4200"),
    ("drayage", "flatbed"): Decimal("1.2700"),
    ("flatbed", "truckload"): Decimal("0.9100"),
    ("flatbed", "ltl"): Decimal("1.0900"),
    ("flatbed", "drayage"): Decimal("0.7000"),
}


@dataclass(frozen=True)
class ConversionRequest:
    source_mode: str
    target_mode: str
    weight_lb: int
    distance_miles: int
    stops: int = 2
    residential: bool = False
    hazmat: bool = False
    cross_border: bool = False
    overdimensional: bool = False


@dataclass(frozen=True)
class ConversionTerms:
    heavy_weight_threshold_lb: int = 30000
    long_haul_threshold_miles: int = 1000
    stop_surcharge_per_extra_stop: Decimal = Decimal("0.0150")
    max_stop_surcharge: Decimal = Decimal("0.0600")
    short_drayage_max_miles: int = 25
    short_drayage_factor: Decimal = Decimal("0.5800")


def _validate(req: ConversionRequest) -> None:
    modes = {"truckload", "ltl", "drayage", "flatbed"}
    if req.source_mode not in modes or req.target_mode not in modes:
        raise ValueError("unsupported mode")
    if req.source_mode == req.target_mode:
        raise ValueError("source and target modes must differ")
    if req.weight_lb <= 0 or req.distance_miles <= 0:
        raise ValueError("weight and distance must be positive")
    if req.stops < 1:
        raise ValueError("stops must be at least 1")


def _base_factor(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.source_mode == "drayage" and req.distance_miles <= terms.short_drayage_max_miles:
        if req.target_mode == "truckload":
            return terms.short_drayage_factor
    return _BASE_FACTORS[(req.source_mode, req.target_mode)]


def _weight_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.target_mode == "ltl":
        if req.weight_lb < 5000:
            return Decimal("0.0800")
        if req.weight_lb > 20000:
            return Decimal("-0.0500")
    if req.weight_lb >= terms.heavy_weight_threshold_lb and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("0.0400")
    return Decimal("0.0000")


def _distance_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.distance_miles < 50 and req.target_mode == "ltl":
        return Decimal("0.0600")
    if req.distance_miles >= terms.long_haul_threshold_miles and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("-0.0300")
    return Decimal("0.0000")


def _accessorial_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    adj = Decimal("0.0000")
    extra_stops = max(req.stops - 2, 0)
    stop_adj = terms.stop_surcharge_per_extra_stop * extra_stops
    if stop_adj > terms.max_stop_surcharge:
        stop_adj = terms.max_stop_surcharge
    adj += stop_adj
    if req.residential and req.target_mode == "ltl":
        adj += Decimal("0.0450")
    if req.hazmat:
        adj += Decimal("0.0101") if req.target_mode == "drayage" else Decimal("0.0250")
    if req.cross_border and req.target_mode in {"truckload", "flatbed"}:
        adj += Decimal("0.0350")
    if req.overdimensional and req.target_mode == "flatbed":
        adj += Decimal("0.0700")
    return adj


def calculate_mode_conversion_factor(
    req: ConversionRequest, terms: ConversionTerms = ConversionTerms()
) -> Decimal:
    """Return the equivalent factor from source mode pricing to target mode pricing."""
    _validate(req)
    factor = _base_factor(req, terms)
    factor += _weight_adjustment(req, terms)
    factor += _distance_adjustment(req, terms)
    factor += _accessorial_adjustment(req, terms)
    if factor <= MIN_FACTOR:
        factor = MIN_FACTOR
    return factor.quantize(FOUR_PLACES, rounding=ROUND_HALF_UP)

tests/test_scorecard.py:
from datetime import datetime, timedelta

from scorecard import Delivery, on_time_percentage, scorecard_counts

WINDOW_END = datetime(2026, 9, 14, 12, 0)


def delivered(load_id, minutes_after_window, code=None):
    return Delivery(
        load_id=load_id,
        window_end=WINDOW_END,
        delivered_at=WINDOW_END + timedelta(minutes=minutes_after_window),
        delay_code=code,
    )


def test_all_on_time_is_100():
    loads = [delivered("A", -90), delivered("B", 0), delivered("C", 10)]
    assert on_time_percentage(loads) == 100.0


def test_cancelled_and_in_transit_loads_are_not_measured():
    loads = [
        delivered("A", 0),
        delivered("B", 120),
        Delivery("C", WINDOW_END, status="cancelled"),
        Delivery("D", WINDOW_END, status="in_transit"),
    ]
    assert on_time_percentage(loads) == 50.0


def test_on_time_load_with_a_delay_code_still_counts():
    loads = [delivered("A", 5, code="CUST"), delivered("B", 90)]
    assert on_time_percentage(loads) == 50.0


def test_counts_breakdown():
    loads = [
        delivered("A", 0),
        delivered("B", 45, code="WX"),
        delivered("C", 45, code="CARR"),
        Delivery("D", WINDOW_END, status="cancelled"),
    ]
    assert scorecard_counts(loads) == {"on_time": 1, "late": 1, "excused": 1, "skipped": 1}


def test_empty_period_is_none():
    assert on_time_percentage([]) is None

residential_delivery_fee.py:
"""Residential delivery charges for shipments tendered to homes and similar non-commercial sites.

The billing service calls ``calculate_residential_delivery_fee`` once per shipment when
rating an accessorial. Standard Tidewater rules are:

* No residential fee applies when the destination is commercial.
* Parcel moves use weight breaks with a surcharge for oversized pieces.
* LTL moves use pallet and weight thresholds; very small dock-friendly drops get a
  reduced minimum fee.
* Remote residential destinations add a fixed tariff on top of the base fee.
* Contract customers may waive the fee entirely, receive a percent discount, or be
  subject to a per-shipment cap. Discounts apply before the cap.
* Charges are rounded half up to the cent, and oversized or remote surcharges are not
  assessed when the residential fee is fully waived.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
PARCEL_BASE_UNDER_70 = Decimal("4.50")
PARCEL_BASE_70_TO_150 = Decimal("8.00")
PARCEL_OVERSIZE_SURCHARGE = Decimal("12.50")
LTL_MINIMUM_FEE = Decimal("32.00")
LTL_SMALL_DROP_FEE = Decimal("18.00")
LTL_HEAVY_FEE = Decimal("48.00")
LTL_EXTRA_HEAVY_FEE = Decimal("72.00")
REMOTE_SURCHARGE = Decimal("9.75")


@dataclass(frozen=True)
class ShipmentFacts:
    destination_type: str
    mode: str
    billed_weight_lb: Decimal
    pieces: int = 1
    pallets: int = 0
    longest_side_in: int = 0
    remote_zip: bool = False
    liftgate_requested: bool = False


@dataclass(frozen=True)
class ResidentialTariff:
    residential_waived: bool = False
    discount_percent: Decimal = Decimal("0")
    shipment_cap: Decimal | None = None


def _validate(shipment: ShipmentFacts, tariff: ResidentialTariff) -> None:
    if shipment.destination_type not in {"residential", "commercial"}:
        raise ValueError("destination_type must be 'residential' or 'commercial'")
    if shipment.mode not in {"parcel", "ltl"}:
        raise ValueError("mode must be 'parcel' or 'ltl'")
    if shipment.billed_weight_lb < 0:
        raise ValueError("billed_weight_lb cannot be negative")
    if shipment.pieces < 1:
        raise ValueError("pieces must be at least 1")
    if shipment.pallets < 0:
        raise ValueError("pallets cannot be negative")
    if not (Decimal("0") <= tariff.discount_percent <= Decimal("100")):
        raise ValueError("discount_percent must be between 0 and 100")
    if tariff.shipment_cap is not None and tariff.shipment_cap < 0:
        raise ValueError("shipment_cap cannot be negative")


def _parcel_fee(shipment: ShipmentFacts) -> Decimal:
    if shipment.billed_weight_lb <= Decimal("70"):
        base = PARCEL_BASE_UNDER_70
    else:
        base = PARCEL_BASE_70_TO_150
    if shipment.longest_side_in > 49 or shipment.billed_weight_lb > Decimal("120"):
        base += PARCEL_OVERSIZE_SURCHARGE
    return base


def _ltl_fee(shipment: ShipmentFacts) -> Decimal:
    if (
        shipment.billed_weight_lb <= Decimal("150")
        and shipment.pallets == 0
        and not shipment.liftgate_requested
    ):
        return LTL_SMALL_DROP_FEE
    if shipment.billed_weight_lb > Decimal("1200") or shipment.pallets >= 4:
        return LTL_EXTRA_HEAVY_FEE
    if shipment.billed_weight_lb > Decimal("500") or shipment.pallets >= 2:
        return LTL_HEAVY_FEE
    return LTL_MINIMUM_FEE


def _apply_discount(amount: Decimal, discount_percent: Decimal) -> Decimal:
    if discount_percent == 0:
        return amount
    multiplier = (Decimal("100") - discount_percent) / Decimal("100")
    return amount * multiplier


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_residential_delivery_fee(
    shipment: ShipmentFacts, tariff: ResidentialTariff = ResidentialTariff()
) -> Decimal:
    """Residential delivery fee owed for one shipment.

    Residential fees apply only to residential destinations. Parcel thresholds are at
    70 lb and 120 lb, with an oversize trigger above 48 inches on the longest side.
    LTL thresholds are small-drop, heavy, and extra-heavy breaks. A remote zip code
    adds a fixed surcharge after the mode-based fee is determined. Contract discounts
    then apply, followed by any cap.
    """
    _validate(shipment, tariff)
    if shipment.destination_type == "commercial" or tariff.residential_waived:
        return Decimal("0.00")
    amount = _parcel_fee(shipment) if shipment.mode == "parcel" else _ltl_fee(shipment)
    if shipment.remote_zip:
        amount += REMOTE_SURCHARGE
    amount = _apply_discount(amount, tariff.discount_percent)
    amount = _apply_cap(amount, tariff.shipment_cap)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)

road_use_tax.py:
"""Road-use tax liability for one tractor for one filing period.

Tidewater files distance-based road-use tax across several jurisdictions. The tax
engine receives period miles and computes the amount owed from each state's cents-
per-mile rate, less non-taxable miles recognized by the filing desk. Business rules:

* Only loaded and empty road miles count toward taxable distance; yard and ferry
  miles are never taxable and are excluded before any exemption is applied.
* Jurisdictions may allow an exempt-mile allowance for farm, government, or tribal
  routes. Exempt miles cannot exceed road miles.
* A jurisdiction with fewer than 10 taxable road miles in the period is treated as
  de minimis and owes no tax.
* Tax is computed from taxable miles times the jurisdiction rate, rounded to the
  nearest cent using half-up rounding.
* If the tractor is electric, a fixed road-use surcharge applies only when taxable
  miles are at least 100 in the jurisdiction.
* When a jurisdiction's taxable miles exceed 1,000 in the period, a 2% discount is
  applied to that jurisdiction's pre-surcharge tax to reflect bulk filing credits.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
DE_MINIMIS_MILES = Decimal("10")
ELECTRIC_SURCHARGE_THRESHOLD = Decimal("100")
BULK_DISCOUNT_THRESHOLD = Decimal("1000")
BULK_DISCOUNT_RATE = Decimal("0.02")
DEFAULT_ELECTRIC_SURCHARGE = Decimal("15.00")


@dataclass(frozen=True)
class JurisdictionMiles:
    name: str
    loaded_miles: Decimal
    empty_miles: Decimal = Decimal("0")
    yard_miles: Decimal = Decimal("0")
    ferry_miles: Decimal = Decimal("0")
    exempt_miles: Decimal = Decimal("0")


@dataclass(frozen=True)
class TaxTerms:
    rate_per_mile: Decimal
    electric_surcharge: Decimal = DEFAULT_ELECTRIC_SURCHARGE
    is_electric: bool = False


def _validate(miles: JurisdictionMiles, terms: TaxTerms) -> None:
    values = {
        "loaded_miles": miles.loaded_miles,
        "empty_miles": miles.empty_miles,
        "yard_miles": miles.yard_miles,
        "ferry_miles": miles.ferry_miles,
        "exempt_miles": miles.exempt_miles,
        "rate_per_mile": terms.rate_per_mile,
        "electric_surcharge": terms.electric_surcharge,
    }
    for field, value in values.items():
        if value < 0:
            raise ValueError(f"{field} cannot be negative: {value}")


def _road_miles(miles: JurisdictionMiles) -> Decimal:
    return miles.loaded_miles + miles.empty_miles


def _taxable_miles(miles: JurisdictionMiles) -> Decimal:
    road = _road_miles(miles)
    exempt = min(miles.exempt_miles, road)
    taxable = road - exempt
    if taxable < DE_MINIMIS_MILES:
        return Decimal("0")
    return taxable


def _base_tax(taxable_miles: Decimal, rate_per_mile: Decimal) -> Decimal:
    amount = taxable_miles * rate_per_mile
    if taxable_miles > BULK_DISCOUNT_THRESHOLD:
        amount = amount * (Decimal("2") - BULK_DISCOUNT_RATE)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _surcharge(taxable_miles: Decimal, terms: TaxTerms) -> Decimal:
    if not terms.is_electric:
        return Decimal("0.00")
    if taxable_miles < ELECTRIC_SURCHARGE_THRESHOLD:
        return Decimal("0.00")
    return terms.electric_surcharge.quantize(CENT, rounding=ROUND_HALF_UP)


def calculate_road_use_tax(miles: JurisdictionMiles, terms: TaxTerms) -> Decimal:
    """Return tax owed for one jurisdiction for one filing period.

    Yard and ferry miles are ignored entirely. Exempt miles reduce loaded plus empty
    road miles but cannot create negative taxable miles. Fewer than 10 taxable miles
    produces no tax and no electric surcharge. For larger periods, tax is based on
    ``terms.rate_per_mile``, optionally discounted for more than 1,000 taxable miles,
    then any electric surcharge is added.
    """
    _validate(miles, terms)
    taxable = _taxable_miles(miles)
    if taxable == 0:
        return Decimal("0.00")
    return _base_tax(taxable, terms.rate_per_mile) + _surcharge(taxable, terms)

billing_weight.py:
"""Billable weight for LTL shipments.

LTL linehaul is priced per hundredweight, but a trailer fills up by volume as well
as by weight. Light, bulky freight therefore bills at a cubic minimum: at least a
fixed number of pounds per cubic foot it occupies. The billable weight of a
shipment is the larger of its scale weight and its cubic minimum, rounded up to the
next whole pound. Rating calls ``billable_weight`` for every LTL shipment.
"""

import math
from dataclasses import dataclass
from decimal import Decimal

CUBIC_MINIMUM_LB_PER_FT3 = Decimal("6")
CUBIC_INCHES_PER_FOOT = Decimal("1728")


@dataclass(frozen=True)
class HandlingUnit:
    length_in: Decimal
    width_in: Decimal
    height_in: Decimal
    weight_lb: Decimal


@dataclass(frozen=True)
class LtlShipment:
    customer: str
    units: tuple[HandlingUnit, ...]


def cubic_feet(unit: HandlingUnit) -> Decimal:
    if min(unit.length_in, unit.width_in, unit.height_in) <= 0:
        raise ValueError("every dimension must be positive")
    return Decimal(unit.length_in) * Decimal(unit.width_in) * Decimal(unit.height_in) / CUBIC_INCHES_PER_FOOT


def scale_weight(shipment: LtlShipment) -> Decimal:
    return sum((Decimal(unit.weight_lb) for unit in shipment.units), Decimal("0"))


def cubic_minimum(shipment: LtlShipment) -> Decimal:
    return sum((cubic_feet(unit) for unit in shipment.units), Decimal("0")) * CUBIC_MINIMUM_LB_PER_FT3


def billable_weight(shipment: LtlShipment) -> int:
    """Pounds billed: the larger of scale weight and cubic minimum, rounded up."""
    if not shipment.units:
        raise ValueError("shipment has no handling units")
    return math.ceil(max(scale_weight(shipment), cubic_minimum(shipment)))

delivery_window.py:
"""Receiving windows at consignee facilities, and how an ETA sits against them.

Facilities publish receiving hours in their own local time, e.g. 08:00-16:00, or
22:00-06:00 for night receiving (the window closes the next morning). Dispatch
compares each truck's ETA, which routing computes in UTC, against the window to
decide whether to call ahead, re-sequence stops or book a new appointment.

All durations here are real elapsed time. A night window that spans the autumn
clock change is nine hours long, not eight.
"""

from dataclasses import dataclass
from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

EARLY = "early"
ON_TIME = "on_time"
LATE = "late"


@dataclass(frozen=True)
class Window:
    opens: datetime  # aware, facility local time
    closes: datetime

    @property
    def zone(self) -> ZoneInfo:
        return self.opens.tzinfo


def receiving_window(day: date, open_at: time, close_at: time, facility_tz: str) -> Window:
    """The window that opens on ``day``; a close at or before the open is next day."""
    zone = ZoneInfo(facility_tz)
    opens = datetime.combine(day, open_at, tzinfo=zone)
    close_day = day + timedelta(days=1) if close_at <= open_at else day
    closes = datetime.combine(close_day, close_at, tzinfo=zone)
    return Window(opens, closes)


def _require_aware(moment: datetime) -> datetime:
    if moment.tzinfo is None:
        raise ValueError("ETA must be timezone-aware")
    return moment


def _elapsed_minutes(start: datetime, end: datetime) -> float:
    """Minutes from ``start`` to ``end``, measured in UTC."""
    return (end.astimezone(timezone.utc) - start.astimezone(timezone.utc)).total_seconds() / 60


def window_minutes(window: Window) -> float:
    return _elapsed_minutes(window.opens, window.closes)


def slack_minutes(eta: datetime, window: Window) -> float:
    """Minutes from the ETA until the window closes; negative means late."""
    local_eta = _require_aware(eta).astimezone(window.zone)
    return _elapsed_minutes(local_eta, window.closes)


def window_status(eta: datetime, window: Window) -> str:
    """EARLY before the window opens, LATE after it closes, else ON_TIME."""
    local_eta = _require_aware(eta).astimezone(window.zone)
    if _elapsed_minutes(window.opens, local_eta) < 0:
        return EARLY
    if slack_minutes(eta, window) < 0:
        return LATE
    return ON_TIME


def latest_departure(window: Window, drive_minutes: float) -> datetime:
    """The latest UTC departure from the previous stop that still makes the window."""
    return window.closes.astimezone(timezone.utc) - timedelta(minutes=drive_minutes)

edi_210_charge_mapping.py:
"""Normalize EDI 210 freight invoice line items into invoice charge categories.

Business rules:
- Carriers send line items with an EDI accessorial code, a free-text description, and an amount.
- Negative amounts are treated as credits and map to the ``credit`` category regardless of code.
- Zero-dollar lines map to ``ignore`` because they do not affect settlement.
- The line-haul code ``400`` normally maps to ``linehaul`` but maps to ``fuel`` when the
  description clearly says fuel surcharge.
- Known accessorial codes map directly: ``405`` and ``FSC`` to fuel, ``DET`` and ``DLY`` to
  detention, ``LUM`` and ``HND`` to lumper, ``TON`` to overweight, ``STP`` to stopoff,
  ``LAY`` to layover, ``BOR`` to border, and ``MSC`` to misc.
- Description keywords can override an unknown or generic code. Description matching is case-
  insensitive and checks practical phrases used by billing teams.
- Small positive uncoded amounts under $25.00 default to ``misc``; amounts from $25.00 and up
  default to ``other``. Generic code ``999`` follows the same fallback.
- If both code and description suggest different non-credit categories, the description wins only
  for clear fuel, detention, and lumper phrases; otherwise the explicit code wins.
- Amounts are rounded to cents with half-up rounding before threshold checks.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
SMALL_MISC_LIMIT = Decimal("25.00")


@dataclass(frozen=True)
class EDI210ChargeLine:
    amount: Decimal
    code: str | None = None
    description: str = ""


@dataclass(frozen=True)
class MappedCharge:
    category: str
    normalized_amount: Decimal
    source: str


def _normalize_amount(amount: Decimal) -> Decimal:
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _clean_code(code: str | None) -> str:
    if code is None:
        return ""
    return code.strip().upper()


def _clean_text(text: str) -> str:
    return " ".join(text.strip().lower().split())


def _category_from_description(text: str) -> str | None:
    if not text:
        return None
    if "fuel surcharge" in text or text == "fuel" or text.startswith("fsc"):
        return "fuel"
    if "detention" in text or "delay time" in text or "driver delay" in text:
        return "detention"
    if "lumper" in text or "unloading" in text or "loading assist" in text:
        return "lumper"
    if "line haul" in text or "linehaul" in text or text == "freight":
        return "linehaul"
    if "stop off" in text or "stopoff" in text:
        return "stopoff"
    return None


def _category_from_code(code: str) -> str | None:
    code_map = {
        "400": "linehaul",
        "405": "fuel",
        "FSC": "fuel",
        "DET": "detention",
        "DLY": "detention",
        "LUM": "lumper",
        "HND": "lumper",
        "TON": "overweight",
        "STP": "stopoff",
        "LAY": "layover",
        "BOR": "border",
        "MSC": "misc",
    }
    return code_map.get(code)


def _fallback_category(amount: Decimal) -> str:
    if amount < SMALL_MISC_LIMIT:
        return "misc"
    return "other"


def map_edi_210_charges(line: EDI210ChargeLine) -> MappedCharge:
    """Map one EDI 210 charge line to a normalized invoice category.

    Returns the chosen category, the rounded amount, and a short source marker showing
    which rule decided the mapping.
    """
    amount = _normalize_amount(line.amount)
    if amount < Decimal("0.00"):
        return MappedCharge("credit", amount, "amount")
    if amount == Decimal("0.00"):
        return MappedCharge("ignore", amount, "amount")

    code = _clean_code(line.code)
    text = _clean_text(line.description)
    desc_category = _category_from_description(text)
    code_category = _category_from_code(code)

    if code == "400" and desc_category == "fuel":
        return MappedCharge("fuel", amount, "description")

    if desc_category in {"fuel", "detention", "lumper"}:
        if code_category is None or code_category == "misc" or code == "999":
            return MappedCharge(desc_category, amount, "description")

    if code_category is not None:
        return MappedCharge(code_category, amount, "code")

    if desc_category is not None:
        return MappedCharge(desc_category, amount, "description")

    if code == "999" or code == "":
        return MappedCharge(_fallback_category(amount), amount, "fallback")

    return MappedCharge("other", amount, "fallback")

hazmat.py:
"""Hazmat handling on truckload and LTL loads.

Two separate questions are answered here. ``requires_placards`` says whether the
truck must display hazmat placards, which dispatch uses to pick a driver with the
hazmat endorsement: a load needs placards at 1,001 lb or more aggregate hazmat
weight, or for any amount of a Table 1 material. ``hazmat_surcharge`` is what the
customer pays for hazmat on the load, which settlement adds as an accessorial.
"""

from dataclasses import dataclass
from decimal import Decimal

HAZMAT_SURCHARGE = Decimal("150.00")
PLACARD_THRESHOLD_LB = Decimal("1001")
# Hazard classes placarded at any quantity (49 CFR 172.504 Table 1, simplified).
TABLE_1_CLASSES = frozenset({"1.1", "1.2", "1.3", "2.3", "4.3", "6.1-PIH", "7"})


@dataclass(frozen=True)
class FreightLine:
    description: str
    weight_lb: Decimal
    un_number: str | None = None
    hazard_class: str | None = None

    @property
    def is_hazmat(self) -> bool:
        return self.un_number is not None


@dataclass(frozen=True)
class Load:
    load_id: str
    customer: str
    lines: tuple[FreightLine, ...]


def hazmat_weight(load: Load) -> Decimal:
    return sum((line.weight_lb for line in load.lines if line.is_hazmat), Decimal("0"))


def requires_placards(load: Load) -> bool:
    if any(line.is_hazmat and line.hazard_class in TABLE_1_CLASSES for line in load.lines):
        return True
    return hazmat_weight(load) >= PLACARD_THRESHOLD_LB


def hazmat_surcharge(load: Load) -> Decimal:
    """The hazmat accessorial: a flat charge for any hazmat on the load."""
    if any(line.is_hazmat for line in load.lines):
        return HAZMAT_SURCHARGE
    return Decimal("0.00")

invoice_dates.py:
"""Invoice and due dates for delivered loads, in the consignee's local time.

The nightly billing batch invoices every load delivered since the last run. Per
our customer contracts, a load's invoice date is the calendar date of delivery
where it was delivered (the consignee's time zone), not where we are and not UTC.
Due dates follow from the customer's net terms; one that lands on a weekend moves
to the following Monday.

Delivery timestamps come from the ELD/POD feed as aware UTC datetimes. Consignee
time zones are IANA names from the facility record ("America/New_York").
"""

from dataclasses import dataclass
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo

DEFAULT_TERMS_DAYS = 30


@dataclass(frozen=True)
class Delivery:
    load_id: str
    delivered_at: datetime
    consignee_tz: str
    terms_days: int = DEFAULT_TERMS_DAYS


@dataclass(frozen=True)
class InvoiceDates:
    invoice_date: date
    due_date: date


def _require_aware(moment: datetime, what: str) -> datetime:
    if moment.tzinfo is None or moment.utcoffset() is None:
        raise ValueError(f"{what} must be timezone-aware")
    return moment.astimezone(timezone.utc)


def _zones(deliveries: list[Delivery]) -> dict[str, ZoneInfo]:
    """Each consignee zone in the batch, loaded once."""
    return {name: ZoneInfo(name) for name in {d.consignee_tz for d in deliveries}}


def _local_delivery_date(delivered_at: datetime, zone: ZoneInfo) -> date:
    """The calendar date at the consignee when the load was delivered.

    The zone is applied at the delivery instant, so the date uses the UTC offset
    that was in force then (EDT or EST, PDT or PST).
    """
    return delivered_at.astimezone(zone).date()


def _roll_off_weekend(day: date) -> date:
    # Saturday -> Monday, Sunday -> Monday.
    if day.weekday() >= 5:
        return day + timedelta(days=7 - day.weekday())
    return day


def due_date(invoice_date: date, terms_days: int) -> date:
    if terms_days < 0:
        raise ValueError("terms_days must be non-negative")
    return _roll_off_weekend(invoice_date + timedelta(days=terms_days))


def invoice_dates_for_batch(deliveries: list[Delivery], run_at: datetime) -> dict[str, InvoiceDates]:
    """Invoice and due dates for every load delivered by ``run_at``.

    Loads delivered after ``run_at`` are left for the next run. All timestamps
    must be timezone-aware.
    """
    run_at = _require_aware(run_at, "run_at")
    zones = _zones(deliveries)
    dates = {}
    for delivery in deliveries:
        delivered_at = _require_aware(delivery.delivered_at, f"{delivery.load_id} delivered_at")
        if delivered_at > run_at:
            continue
        invoice_date = _local_delivery_date(delivered_at, zones[delivery.consignee_tz])
        dates[delivery.load_id] = InvoiceDates(invoice_date, due_date(invoice_date, delivery.terms_days))
    return dates

invoice_lines.py:
"""Customer invoice lines and totals for settled loads.

Each charge on a load becomes one invoice line: quantity times unit rate (miles x
rate per mile, hours x detention rate, pallets x handling rate). Rates in the rate
engine carry up to four decimal places, so line amounts are rounded to the cent,
half up, before they are printed.

Customers on quick-pay terms get a 2% discount for paying within 10 days; it is
printed as its own negative line under the subtotal.

Customer AP systems (Hartline's included) reconcile every invoice by adding up the
printed lines, so the subtotal must equal the sum of the line amounts as printed.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
QUICK_PAY_RATE = Decimal("0.02")


@dataclass(frozen=True)
class Charge:
    description: str
    quantity: Decimal
    unit_rate: Decimal


@dataclass(frozen=True)
class InvoiceLine:
    description: str
    amount: Decimal


@dataclass(frozen=True)
class Invoice:
    lines: list[InvoiceLine]
    subtotal: Decimal
    quick_pay_discount: Decimal
    total: Decimal


def _to_cents(amount: Decimal) -> Decimal:
    # ROUND_HALF_UP rounds away from zero, so credits round the same way as charges.
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _extended(charge: Charge) -> Decimal:
    """Quantity times rate, unrounded."""
    return Decimal(charge.quantity) * Decimal(charge.unit_rate)


def _printed_lines(charges: list[Charge]) -> list[InvoiceLine]:
    return [InvoiceLine(charge.description, _to_cents(_extended(charge))) for charge in charges]


def _quick_pay_discount(subtotal: Decimal) -> Decimal:
    return _to_cents(subtotal * QUICK_PAY_RATE)


def build_invoice(charges: list[Charge], quick_pay: bool = False) -> Invoice:
    """Build the printed invoice for one load's charges.

    Credits (negative unit rates) are allowed. With ``quick_pay``, a 2% discount
    of the subtotal is taken off the total.
    """
    if not charges:
        raise ValueError("an invoice needs at least one charge")
    lines = _printed_lines(charges)
    subtotal = sum((line.amount for line in lines), Decimal("0.00"))
    discount = _quick_pay_discount(subtotal) if quick_pay else Decimal("0.00")
    return Invoice(
        lines=lines,
        subtotal=subtotal,
        quick_pay_discount=discount,
        total=subtotal - discount,
    )

lane_rates.py:
"""Contract lane rate lookup with fallbacks.

Customer contracts price linehaul per mile by lane. Pricing loads them at three
levels of detail, most specific first:

    zip3        origin ZIP3 -> destination ZIP3   ("972" -> "837")
    zip3_state  origin ZIP3 -> destination state  ("972" -> "ID")
    state       origin state -> destination state ("OR" -> "ID")

Every rate has an effective date and an optional expiry date (inclusive). Rates
get renegotiated lane by lane, so the specific lanes often lapse before the
state-level rates do. A lookup uses the most specific level that has a rate in
effect on the ship date, and falls back to the customer's default per-mile rate
when no level does. If two rates at one level are in effect at once, the one with
the later effective date wins: it is the newer contract amendment.
"""

from dataclasses import dataclass
from datetime import date
from decimal import ROUND_HALF_UP, Decimal

LEVELS = ("zip3", "zip3_state", "state")
CENT = Decimal("0.01")


@dataclass(frozen=True)
class LaneRate:
    level: str
    origin: str
    dest: str
    rate_per_mile: Decimal
    effective: date
    expires: date | None = None


@dataclass(frozen=True)
class Shipment:
    origin_zip: str
    origin_state: str
    dest_zip: str
    dest_state: str
    ship_date: date


@dataclass(frozen=True)
class RateMatch:
    rate_per_mile: Decimal
    level: str


RateTable = dict[tuple[str, str, str], list[LaneRate]]


def build_rate_table(rates: list[LaneRate]) -> RateTable:
    table: RateTable = {}
    for rate in rates:
        if rate.level not in LEVELS:
            raise ValueError(f"unknown lane level {rate.level!r}")
        table.setdefault((rate.level, rate.origin, rate.dest), []).append(rate)
    return table


def _candidate_keys(shipment: Shipment) -> list[tuple[str, str, str]]:
    origin3, dest3 = shipment.origin_zip[:3], shipment.dest_zip[:3]
    return [
        ("zip3", origin3, dest3),
        ("zip3_state", origin3, shipment.dest_state),
        ("state", shipment.origin_state, shipment.dest_state),
    ]


def _in_effect(rates: list[LaneRate], on: date) -> list[LaneRate]:
    return [r for r in rates if r.effective <= on and (r.expires is None or on <= r.expires)]


def _most_specific(table: RateTable, shipment: Shipment) -> tuple[str | None, list[LaneRate]]:
    """The most specific level with a rate in effect on the ship date, and those rates."""
    for key in _candidate_keys(shipment):
        live = _in_effect(table.get(key, []), shipment.ship_date)
        if live:
            return key[0], live
    return None, []


def lookup_lane_rate(
    table: RateTable, shipment: Shipment, default_rate: Decimal | None = None
) -> RateMatch:
    """The per-mile rate for ``shipment``, and which level it came from.

    Raises LookupError if no lane rate applies and the customer has no default.
    """
    level, live = _most_specific(table, shipment)
    if live:
        newest = max(live, key=lambda rate: rate.effective)
        return RateMatch(newest.rate_per_mile, level)
    if default_rate is None:
        raise LookupError(f"no lane rate for {shipment.origin_zip} -> {shipment.dest_zip}")
    return RateMatch(default_rate, "default")


def linehaul(table: RateTable, shipment: Shipment, miles: Decimal, default_rate: Decimal | None = None) -> Decimal:
    """Linehaul dollars for the shipment's miles, rounded to the cent."""
    rate = lookup_lane_rate(table, shipment, default_rate).rate_per_mile
    return (rate * miles).quantize(CENT, rounding=ROUND_HALF_UP)

linear_feet.py:
"""Linear feet of trailer floor a palletized LTL shipment takes up.

LTL and volume quotes price by linear feet: how much of a 53' trailer's length the
freight occupies. Pallets load in rows across the trailer. A row holds two pallets
side by side when two fit inside the 100" usable width (a standard 48x40 does,
loaded with the 48" side along the trailer), otherwise one. A row is as deep as the
pallet's length.

Stackable pallets double-stack when two of them fit under the 102" usable height,
so two stacked pallets take one floor position. A stacked pair and a floor-only
pallet of the same footprint can share a row. Pallets with different footprints
don't share rows, since mixed rows don't load square.

Quoting calls ``linear_feet_for_shipment`` with the shipment's pallet lines.
"""

import math
from collections import defaultdict
from dataclasses import dataclass

TRAILER_WIDTH_IN = 100
TRAILER_HEIGHT_IN = 102
TRAILER_LENGTH_FT = 53


@dataclass(frozen=True)
class PalletLine:
    """One line of the bill of lading: ``count`` pallets of the same build."""

    count: int
    length_in: int = 48
    width_in: int = 40
    height_in: int = 48
    stackable: bool = False

    @property
    def footprint(self) -> tuple[int, int]:
        return (self.length_in, self.width_in)


def _per_row(width_in: int) -> int:
    return 2 if 2 * width_in <= TRAILER_WIDTH_IN else 1


def _floor_positions(line: PalletLine) -> int:
    """Floor positions one line needs, after double-stacking."""
    if line.stackable and 2 * line.height_in <= TRAILER_HEIGHT_IN:
        return math.ceil(line.count / 2)
    return line.count


def _validate(lines: list[PalletLine]) -> None:
    for line in lines:
        if line.count < 0:
            raise ValueError("pallet count must be positive")
        if line.width_in > TRAILER_WIDTH_IN or line.height_in > TRAILER_HEIGHT_IN:
            raise ValueError(f"pallet {line.footprint} does not fit in a trailer")


def _positions_by_footprint(lines: list[PalletLine]) -> dict[tuple[int, int], int]:
    positions: dict[tuple[int, int], int] = defaultdict(int)
    for line in lines:
        positions[line.footprint] += _floor_positions(line)
    return positions


def _row_inches(lines: list[PalletLine]) -> int:
    """Total trailer length in inches, footprint by footprint."""
    total = 0
    for (length_in, width_in), positions in _positions_by_footprint(lines).items():
        rows = math.ceil(positions / _per_row(width_in))
        total += rows * length_in
    return total


def linear_feet_for_shipment(lines: list[PalletLine]) -> int:
    """Linear feet for the shipment, rounded up to the whole foot.

    Raises ValueError if the freight would not fit on one 53' trailer.
    """
    if not lines:
        raise ValueError("shipment has no pallets")
    _validate(lines)
    feet = math.ceil(_row_inches(lines) / 12)
    if feet > TRAILER_LENGTH_FT:
        raise ValueError(f"{feet} linear feet exceeds a {TRAILER_LENGTH_FT}' trailer")
    return feet

maintenance_fund_contribution.py:
"""Maintenance-fund contributions withheld from owner-operator settlements.

The maintenance fund is an internal escrow used to smooth large repair events. A lease
may fund it three different ways: by loaded mile, as a percentage of linehaul revenue,
or as a flat amount per settlement period. Contributions are calculated per settlement
and rounded to the cent.

Business rules used by Tidewater Freight:
- Exactly one funding basis applies: mileage, revenue percentage, or flat periodic.
- Negative miles or revenue are invalid.
- Loaded miles under 50 do not fund the account on mileage plans.
- Mileage plans charge a per-mile rate only on loaded miles, then add a remote-area
  surcharge of $7.50 when loaded miles exceed 1,200 in a settlement.
- Revenue plans apply only to linehaul revenue, excluding FSC and accessorials. If the
  linehaul revenue is below $300.00, no contribution is withheld.
- Flat periodic plans skip the contribution when the operator is on approved home time
  for 14 or more days in the settlement.
- A settlement may waive up to one missed scheduled contribution per calendar quarter;
  if waived, the contribution is zero.
- The contribution may not exceed the remaining account room below the account cap.
  If the account is already at or above the cap, no contribution is taken.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
REMOTE_SURCHARGE = Decimal("7.50")
MILEAGE_MINIMUM = 50
REVENUE_MINIMUM = Decimal("300.00")
HOME_TIME_WAIVER_DAYS = 14


@dataclass(frozen=True)
class SettlementFacts:
    loaded_miles: int = 0
    linehaul_revenue: Decimal = Decimal("0.00")
    account_balance: Decimal = Decimal("0.00")
    account_cap: Decimal = Decimal("2000.00")
    home_time_days: int = 0
    waived_for_quarter: bool = False


@dataclass(frozen=True)
class MaintenanceFundTerms:
    per_loaded_mile: Decimal | None = None
    revenue_percent: Decimal | None = None
    flat_amount: Decimal | None = None


def _validate_terms(terms: MaintenanceFundTerms) -> None:
    configured = [
        terms.per_loaded_mile is not None,
        terms.revenue_percent is not None,
        terms.flat_amount is not None,
    ]
    if sum(configured) != 1:
        raise ValueError("exactly one funding basis must be configured")
    if terms.per_loaded_mile is not None and terms.per_loaded_mile < 0:
        raise ValueError("per_loaded_mile cannot be negative")
    if terms.revenue_percent is not None and terms.revenue_percent < 0:
        raise ValueError("revenue_percent cannot be negative")
    if terms.flat_amount is not None and terms.flat_amount < 0:
        raise ValueError("flat_amount cannot be negative")


def _validate_facts(facts: SettlementFacts) -> None:
    if facts.loaded_miles < 0:
        raise ValueError("loaded_miles cannot be negative")
    if facts.linehaul_revenue < 0:
        raise ValueError("linehaul_revenue cannot be negative")
    if facts.account_balance < 0:
        raise ValueError("account_balance cannot be negative")
    if facts.account_cap < 0:
        raise ValueError("account_cap cannot be negative")
    if facts.home_time_days < 0:
        raise ValueError("home_time_days cannot be negative")


def _raw_contribution(facts: SettlementFacts, terms: MaintenanceFundTerms) -> Decimal:
    if facts.waived_for_quarter:
        return Decimal("0.00")
    if terms.per_loaded_mile is not None:
        if facts.loaded_miles < MILEAGE_MINIMUM:
            return Decimal("0.00")
        amount = Decimal(facts.loaded_miles) * terms.per_loaded_mile
        if facts.loaded_miles > 1200:
            amount += REMOTE_SURCHARGE
        return amount
    if terms.revenue_percent is not None:
        if facts.linehaul_revenue < REVENUE_MINIMUM:
            return Decimal("0.00")
        return facts.linehaul_revenue * terms.revenue_percent / Decimal("100")
    if facts.home_time_days >= HOME_TIME_WAIVER_DAYS:
        return Decimal("0.00")
    return terms.flat_amount or Decimal("0.00")


def _apply_cap(amount: Decimal, balance: Decimal, cap: Decimal) -> Decimal:
    remaining = cap - balance
    if remaining <= 0:
        return Decimal("0.00")
    if amount > remaining:
        return remaining
    return amount


def calculate_maintenance_fund_contribution(
    facts: SettlementFacts,
    terms: MaintenanceFundTerms,
) -> Decimal:
    """Return the settlement maintenance-fund deduction in dollars.

    The deduction is computed from the configured funding basis, rounded half up to the
    cent, then limited so the resulting account balance does not exceed the cap.
    """
    _validate_facts(facts)
    _validate_terms(terms)
    amount = _raw_contribution(facts, terms).quantize(CENT, rounding=ROUND_HALF_UP)
    return _apply_cap(amount, facts.account_balance, facts.account_cap).quantize(
        CENT, rounding=ROUND_HALF_UP
    )

axle_weights.py:
"""Federal axle weight checks for a loaded tractor-trailer (23 CFR 658.17).

Load planning runs ``check_axle_weights`` on the scale ticket or the planned axle
loads before a truck is dispatched onto the Interstate. The federal limits:

- 20,000 lbs on any single axle.
- 34,000 lbs on a tandem (two axles more than 40" and at most 96" apart).
- 80,000 lbs gross.
- The bridge formula, W = 500 * (L*N/(N-1) + 12*N + 36), on every group of two or
  more consecutive axles: N is the number of axles in the group, L the distance
  in feet between its outer axles, W the most the group may carry. Like the
  published bridge table, W is rounded to the nearest 500 lbs. A group that is
  just one tandem is covered by the tandem limit instead.
- Exception: two consecutive tandems may carry 34,000 lbs each (68,000 together)
  if their outer axles are 36 feet or more apart, even when the formula gives
  less.

Axles are given front to back, with positions in feet from the steer axle.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

SINGLE_LIMIT = 20_000
TANDEM_LIMIT = 34_000
GROSS_LIMIT = 80_000
TANDEM_MAX_SPACING_FT = 8.0
DOUBLE_TANDEM_MIN_SPAN_FT = 36.0
DOUBLE_TANDEM_LIMIT = 68_000


@dataclass(frozen=True)
class Violation:
    rule: str  # "single", "tandem", "gross" or "bridge"
    first_axle: int
    last_axle: int
    weight: int
    limit: int


def bridge_limit(span_ft: float, axles: int) -> int:
    """The bridge formula for ``axles`` axles spread over ``span_ft`` feet."""
    if axles < 2:
        raise ValueError("the bridge formula needs at least two axles")
    raw = 500 * (Decimal(str(span_ft)) * axles / (axles - 1) + 12 * axles + 36)
    return int((raw / 500).quantize(Decimal(1), rounding=ROUND_HALF_UP) * 500)


def _tandem_starts(positions: list[float]) -> set[int]:
    """Indexes of axles that are the front axle of a tandem."""
    return {
        i for i in range(len(positions) - 1)
        if positions[i + 1] - positions[i] <= TANDEM_MAX_SPACING_FT
    }


def _bridge_spans(axle_count: int, tandems: set[int]) -> list[tuple[int, int]]:
    """Every group of two or more consecutive axles, except lone tandems."""
    return [
        (first, last)
        for first in range(axle_count)
        for last in range(first + 1, axle_count)
        if not (last == first + 1 and first in tandems)
    ]


def _span_limit(first: int, last: int, positions: list[float], tandems: set[int]) -> int:
    span = positions[last] - positions[first]
    limit = bridge_limit(span, last - first + 1)
    double_tandem = (
        last - first == 3
        and first in tandems
        and first + 2 in tandems
        and first + 1 not in tandems
        and first + 3 not in tandems
    )
    if double_tandem and span >= DOUBLE_TANDEM_MIN_SPAN_FT:
        limit = max(limit, DOUBLE_TANDEM_LIMIT)
    return limit


def check_axle_weights(weights: list[int], positions: list[float]) -> list[Violation]:
    """Every federal limit the axle loads break; an empty list means legal."""
    if len(weights) != len(positions) or len(weights) < 2:
        raise ValueError("need a weight and a position for each of at least two axles")
    if any(b <= a for a, b in zip(positions, positions[1:])):
        raise ValueError("axle positions must increase front to back")
    tandems = _tandem_starts(positions)
    in_tandem = tandems | {i + 1 for i in tandems}
    violations = []
    for i, weight in enumerate(weights):
        if i not in in_tandem and weight > SINGLE_LIMIT:
            violations.append(Violation("single", i, i, weight, SINGLE_LIMIT))
    for i in sorted(tandems):
        weight = weights[i] + weights[i + 1]
        if weight > TANDEM_LIMIT:
            violations.append(Violation("tandem", i, i + 1, weight, TANDEM_LIMIT))
    gross = sum(weights)
    if gross > GROSS_LIMIT:
        violations.append(Violation("gross", 0, len(weights) - 1, gross, GROSS_LIMIT))
    for first, last in _bridge_spans(len(weights), tandems):
        weight = sum(weights[first:last + 1])
        limit = _span_limit(first, last, positions, tandems)
        if weight > limit:
            violations.append(Violation("bridge", first, last, weight, limit))
    return violations

bol_reference_parser.py:
"""Normalize bill-of-lading references from raw strings.

The settlement pipeline receives reference strings copied from shipper paperwork and EDI.
This parser extracts stable reference components so matching can ignore punctuation,
spacing, repeated labels, and scanner noise. Business rules:

- Empty tokens and tokens with no letters or digits are ignored.
- Known labels map to canonical prefixes: ``BOL``, ``PO``, ``SO``, and ``PU``.
- A token like ``BOL12345`` or ``PO-7788`` becomes one prefixed reference when the
  prefix is recognized and the remainder is valid.
- Numeric payloads drop leading zeros unless the whole value is zero. Alphanumeric
  payloads keep internal zeros.
- Payloads shorter than 3 characters are ignored, except ``PO`` allows 1 and ``PU``
  allows 1 because some customers use short order and pickup numbers.
- Payloads longer than 12 characters are ignored unless they are all digits, in which
  case the last 12 digits are kept; this handles overflowed scans.
- Duplicate normalized references are suppressed in first-seen order.
- A bare token with no recognizable prefix is treated as ``BOL`` only when it is all
  digits and has normalized length 3 to 10 inclusive.
"""

from dataclasses import dataclass

LABELS = {
    "BOL": "BOL",
    "BILL": "BOL",
    "BILL OF LADING": "BOL",
    "BILL-OF-LADING": "BOL",
    "PO": "PO",
    "P/O": "PO",
    "PURCHASE ORDER": "PO",
    "SO": "SO",
    "SHIPPER ORDER": "SO",
    "PU": "PU",
    "PICKUP": "PU",
}
MIN_LEN = {"BOL": 3, "PO": 1, "SO": 3, "PU": 1}
MAX_LEN = 12
SEPARATORS = " :-#/\\"


@dataclass(frozen=True)
class RawReferenceSet:
    references: tuple[str, ...]


@dataclass(frozen=True)
class ParsedReference:
    prefix: str
    value: str


def _clean(text: str) -> str:
    return " ".join(text.strip().upper().split())


def _payload_chars(text: str) -> str:
    return "".join(ch for ch in text if ch.isalnum())


def _normalize_value(prefix: str, value: str) -> str | None:
    raw = _payload_chars(value)
    if not raw:
        return None
    if raw.isdigit():
        raw = raw.lstrip("0") or "0"
    if len(raw) > MAX_LEN:
        if raw.isdigit():
            raw = raw[-MAX_LEN:]
        else:
            return None
    if len(raw) < MIN_LEN[prefix]:
        return None
    return raw


def _split_prefixed_token(token: str) -> tuple[str, str] | None:
    compact = _clean(token)
    for label, prefix in sorted(LABELS.items(), key=lambda item: len(item[0]), reverse=True):
        if compact == label:
            return None
        if compact.startswith(label):
            remainder = compact[len(label):].lstrip(SEPARATORS)
            if remainder:
                return prefix, remainder
    return None


def _extract_one(token: str, pending_prefix: str | None) -> tuple[ParsedReference | None, str | None]:
    cleaned = _clean(token)
    if not cleaned:
        return None, pending_prefix
    if cleaned in LABELS:
        return None, LABELS[cleaned]
    combined = _split_prefixed_token(cleaned)
    if combined is not None:
        prefix, remainder = combined
        value = _normalize_value(prefix, remainder)
        return (ParsedReference(prefix, value) if value else None), None
    if pending_prefix is not None:
        value = _normalize_value(pending_prefix, cleaned)
        return (ParsedReference(pending_prefix, value) if value else None), None
    raw = _payload_chars(cleaned)
    if raw.isdigit():
        normalized = raw.lstrip("0") or "0"
        if 3 <= len(normalized) <= 10:
            return ParsedReference("BOL", normalized), None
    return None, None


def parse_bol_references(raw: RawReferenceSet) -> tuple[ParsedReference, ...]:
    """Return unique normalized reference components in first-seen order."""
    seen: set[tuple[str, str]] = set()
    parsed: list[ParsedReference] = []
    pending_prefix: str | None = None
    for token in raw.references:
        item, pending_prefix = _extract_one(token, pending_prefix)
        if item is None:
            continue
        key = (item.prefix, item.value)
        if key in seen:
            continue
        seen.add(key)
        parsed.append(item)
    return tuple(parsed)

mode_conversion_factor.py:
"""Equivalent rating factors for converting between freight pricing modes.

Operations normalizes customer rates across truckload, LTL, drayage, and flatbed so
analytics can compare bids on a common basis. The conversion here returns a factor
that multiplies the source mode's amount into an equivalent target-mode amount.

Business rules:
- Base factors are configured per source/target mode pair.
- Weight, distance, and stop count slightly adjust the factor within narrow bands.
- Residential delivery only affects LTL destinations.
- Hazmat applies a small uplift except on drayage, where local port tariffs already
  include most handling.
- Cross-border moves add friction on truckload and flatbed conversions.
- Very short drayage moves under 25 miles use a local minimum factor.
- Flatbed with over-dimensional freight adds an extra uplift.
- Final factors are rounded half up to four decimals and never below 0.2500.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

FOUR_PLACES = Decimal("0.0001")
MIN_FACTOR = Decimal("0.2500")

_BASE_FACTORS = {
    ("truckload", "ltl"): Decimal("1.1800"),
    ("truckload", "drayage"): Decimal("0.7600"),
    ("truckload", "flatbed"): Decimal("1.1200"),
    ("ltl", "truckload"): Decimal("0.8500"),
    ("ltl", "drayage"): Decimal("0.6400"),
    ("ltl", "flatbed"): Decimal("1.0500"),
    ("drayage", "truckload"): Decimal("1.3100"),
    ("drayage", "ltl"): Decimal("1.4200"),
    ("drayage", "flatbed"): Decimal("1.2700"),
    ("flatbed", "truckload"): Decimal("0.9100"),
    ("flatbed", "ltl"): Decimal("1.0900"),
    ("flatbed", "drayage"): Decimal("0.7000"),
}


@dataclass(frozen=True)
class ConversionRequest:
    source_mode: str
    target_mode: str
    weight_lb: int
    distance_miles: int
    stops: int = 2
    residential: bool = False
    hazmat: bool = False
    cross_border: bool = False
    overdimensional: bool = False


@dataclass(frozen=True)
class ConversionTerms:
    heavy_weight_threshold_lb: int = 30000
    long_haul_threshold_miles: int = 1000
    stop_surcharge_per_extra_stop: Decimal = Decimal("0.0150")
    max_stop_surcharge: Decimal = Decimal("0.0600")
    short_drayage_max_miles: int = 25
    short_drayage_factor: Decimal = Decimal("0.5800")


def _validate(req: ConversionRequest) -> None:
    modes = {"truckload", "ltl", "drayage", "flatbed"}
    if req.source_mode not in modes or req.target_mode not in modes:
        raise ValueError("unsupported mode")
    if req.source_mode == req.target_mode:
        raise ValueError("source and target modes must differ")
    if req.weight_lb <= 0 or req.distance_miles <= 0:
        raise ValueError("weight and distance must be positive")
    if req.stops < 1:
        raise ValueError("stops must be at least 1")


def _base_factor(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.source_mode == "drayage" and req.distance_miles <= terms.short_drayage_max_miles:
        if req.target_mode == "truckload":
            return terms.short_drayage_factor
    return _BASE_FACTORS[(req.source_mode, req.target_mode)]


def _weight_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.target_mode == "ltl":
        if req.weight_lb < 5000:
            return Decimal("0.0800")
        if req.weight_lb > 20000:
            return Decimal("-0.0500")
    if req.weight_lb >= terms.heavy_weight_threshold_lb and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("0.0400")
    return Decimal("0.0000")


def _distance_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    if req.distance_miles < 50 and req.target_mode == "ltl":
        return Decimal("0.0600")
    if req.distance_miles >= terms.long_haul_threshold_miles and req.target_mode in {"truckload", "flatbed"}:
        return Decimal("-0.0300")
    return Decimal("0.0000")


def _accessorial_adjustment(req: ConversionRequest, terms: ConversionTerms) -> Decimal:
    adj = Decimal("0.0000")
    extra_stops = max(req.stops - 2, 0)
    stop_adj = terms.stop_surcharge_per_extra_stop * extra_stops
    if stop_adj > terms.max_stop_surcharge:
        stop_adj = terms.max_stop_surcharge
    adj += stop_adj
    if req.residential and req.target_mode == "ltl":
        adj += Decimal("0.0450")
    if req.hazmat:
        adj += Decimal("0.0100") if req.target_mode == "drayage" else Decimal("0.0250")
    if req.cross_border and req.target_mode in {"truckload", "flatbed"}:
        adj += Decimal("0.0350")
    if req.overdimensional and req.target_mode == "flatbed":
        adj += Decimal("0.0700")
    return adj


def calculate_mode_conversion_factor(
    req: ConversionRequest, terms: ConversionTerms = ConversionTerms()
) -> Decimal:
    """Return the equivalent factor from source mode pricing to target mode pricing."""
    _validate(req)
    factor = _base_factor(req, terms)
    factor += _weight_adjustment(req, terms)
    factor += _distance_adjustment(req, terms)
    factor += _accessorial_adjustment(req, terms)
    if factor < MIN_FACTOR:
        factor = MIN_FACTOR
    return factor.quantize(FOUR_PLACES, rounding=ROUND_HALF_UP)

residential_delivery_fee.py:
"""Residential delivery charges for shipments tendered to homes and similar non-commercial sites.

The billing service calls ``calculate_residential_delivery_fee`` once per shipment when
rating an accessorial. Standard Tidewater rules are:

* No residential fee applies when the destination is commercial.
* Parcel moves use weight breaks with a surcharge for oversized pieces.
* LTL moves use pallet and weight thresholds; very small dock-friendly drops get a
  reduced minimum fee.
* Remote residential destinations add a fixed tariff on top of the base fee.
* Contract customers may waive the fee entirely, receive a percent discount, or be
  subject to a per-shipment cap. Discounts apply before the cap.
* Charges are rounded half up to the cent, and oversized or remote surcharges are not
  assessed when the residential fee is fully waived.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
PARCEL_BASE_UNDER_70 = Decimal("4.50")
PARCEL_BASE_70_TO_150 = Decimal("8.00")
PARCEL_OVERSIZE_SURCHARGE = Decimal("12.50")
LTL_MINIMUM_FEE = Decimal("32.00")
LTL_SMALL_DROP_FEE = Decimal("18.00")
LTL_HEAVY_FEE = Decimal("48.00")
LTL_EXTRA_HEAVY_FEE = Decimal("72.00")
REMOTE_SURCHARGE = Decimal("9.75")


@dataclass(frozen=True)
class ShipmentFacts:
    destination_type: str
    mode: str
    billed_weight_lb: Decimal
    pieces: int = 1
    pallets: int = 0
    longest_side_in: int = 0
    remote_zip: bool = False
    liftgate_requested: bool = False


@dataclass(frozen=True)
class ResidentialTariff:
    residential_waived: bool = False
    discount_percent: Decimal = Decimal("0")
    shipment_cap: Decimal | None = None


def _validate(shipment: ShipmentFacts, tariff: ResidentialTariff) -> None:
    if shipment.destination_type not in {"residential", "commercial"}:
        raise ValueError("destination_type must be 'residential' or 'commercial'")
    if shipment.mode not in {"parcel", "ltl"}:
        raise ValueError("mode must be 'parcel' or 'ltl'")
    if shipment.billed_weight_lb < 0:
        raise ValueError("billed_weight_lb cannot be negative")
    if shipment.pieces < 1:
        raise ValueError("pieces must be at least 1")
    if shipment.pallets < 0:
        raise ValueError("pallets cannot be negative")
    if not (Decimal("0") <= tariff.discount_percent <= Decimal("100")):
        raise ValueError("discount_percent must be between 0 and 100")
    if tariff.shipment_cap is not None and tariff.shipment_cap < 0:
        raise ValueError("shipment_cap cannot be negative")


def _parcel_fee(shipment: ShipmentFacts) -> Decimal:
    if shipment.billed_weight_lb <= Decimal("70"):
        base = PARCEL_BASE_UNDER_70
    else:
        base = PARCEL_BASE_70_TO_150
    if shipment.longest_side_in > 48 or shipment.billed_weight_lb > Decimal("120"):
        base += PARCEL_OVERSIZE_SURCHARGE
    return base


def _ltl_fee(shipment: ShipmentFacts) -> Decimal:
    if (
        shipment.billed_weight_lb <= Decimal("150")
        and shipment.pallets == 0
        and not shipment.liftgate_requested
    ):
        return LTL_SMALL_DROP_FEE
    if shipment.billed_weight_lb > Decimal("1200") or shipment.pallets >= 4:
        return LTL_EXTRA_HEAVY_FEE
    if shipment.billed_weight_lb > Decimal("500") or shipment.pallets >= 2:
        return LTL_HEAVY_FEE
    return LTL_MINIMUM_FEE


def _apply_discount(amount: Decimal, discount_percent: Decimal) -> Decimal:
    if discount_percent == 0:
        return amount
    multiplier = (Decimal("100") - discount_percent) / Decimal("100")
    return amount * multiplier


def _apply_cap(amount: Decimal, cap: Decimal | None) -> Decimal:
    if cap is not None and amount > cap:
        return cap
    return amount


def calculate_residential_delivery_fee(
    shipment: ShipmentFacts, tariff: ResidentialTariff = ResidentialTariff()
) -> Decimal:
    """Residential delivery fee owed for one shipment.

    Residential fees apply only to residential destinations. Parcel thresholds are at
    70 lb and 120 lb, with an oversize trigger above 48 inches on the longest side.
    LTL thresholds are small-drop, heavy, and extra-heavy breaks. A remote zip code
    adds a fixed surcharge after the mode-based fee is determined. Contract discounts
    then apply, followed by any cap.
    """
    _validate(shipment, tariff)
    if shipment.destination_type == "commercial" or tariff.residential_waived:
        return Decimal("0.00")
    amount = _parcel_fee(shipment) if shipment.mode == "parcel" else _ltl_fee(shipment)
    if shipment.remote_zip:
        amount += REMOTE_SURCHARGE
    amount = _apply_discount(amount, tariff.discount_percent)
    amount = _apply_cap(amount, tariff.shipment_cap)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)

road_use_tax.py:
"""Road-use tax liability for one tractor for one filing period.

Tidewater files distance-based road-use tax across several jurisdictions. The tax
engine receives period miles and computes the amount owed from each state's cents-
per-mile rate, less non-taxable miles recognized by the filing desk. Business rules:

* Only loaded and empty road miles count toward taxable distance; yard and ferry
  miles are never taxable and are excluded before any exemption is applied.
* Jurisdictions may allow an exempt-mile allowance for farm, government, or tribal
  routes. Exempt miles cannot exceed road miles.
* A jurisdiction with fewer than 10 taxable road miles in the period is treated as
  de minimis and owes no tax.
* Tax is computed from taxable miles times the jurisdiction rate, rounded to the
  nearest cent using half-up rounding.
* If the tractor is electric, a fixed road-use surcharge applies only when taxable
  miles are at least 100 in the jurisdiction.
* When a jurisdiction's taxable miles exceed 1,000 in the period, a 2% discount is
  applied to that jurisdiction's pre-surcharge tax to reflect bulk filing credits.
"""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
DE_MINIMIS_MILES = Decimal("10")
ELECTRIC_SURCHARGE_THRESHOLD = Decimal("100")
BULK_DISCOUNT_THRESHOLD = Decimal("1000")
BULK_DISCOUNT_RATE = Decimal("0.02")
DEFAULT_ELECTRIC_SURCHARGE = Decimal("15.00")


@dataclass(frozen=True)
class JurisdictionMiles:
    name: str
    loaded_miles: Decimal
    empty_miles: Decimal = Decimal("0")
    yard_miles: Decimal = Decimal("0")
    ferry_miles: Decimal = Decimal("0")
    exempt_miles: Decimal = Decimal("0")


@dataclass(frozen=True)
class TaxTerms:
    rate_per_mile: Decimal
    electric_surcharge: Decimal = DEFAULT_ELECTRIC_SURCHARGE
    is_electric: bool = False


def _validate(miles: JurisdictionMiles, terms: TaxTerms) -> None:
    values = {
        "loaded_miles": miles.loaded_miles,
        "empty_miles": miles.empty_miles,
        "yard_miles": miles.yard_miles,
        "ferry_miles": miles.ferry_miles,
        "exempt_miles": miles.exempt_miles,
        "rate_per_mile": terms.rate_per_mile,
        "electric_surcharge": terms.electric_surcharge,
    }
    for field, value in values.items():
        if value < 0:
            raise ValueError(f"{field} cannot be negative: {value}")


def _road_miles(miles: JurisdictionMiles) -> Decimal:
    return miles.loaded_miles + miles.empty_miles


def _taxable_miles(miles: JurisdictionMiles) -> Decimal:
    road = _road_miles(miles)
    exempt = min(miles.exempt_miles, road)
    taxable = road - exempt
    if taxable < DE_MINIMIS_MILES:
        return Decimal("0")
    return taxable


def _base_tax(taxable_miles: Decimal, rate_per_mile: Decimal) -> Decimal:
    amount = taxable_miles * rate_per_mile
    if taxable_miles > BULK_DISCOUNT_THRESHOLD:
        amount = amount * (Decimal("1") - BULK_DISCOUNT_RATE)
    return amount.quantize(CENT, rounding=ROUND_HALF_UP)


def _surcharge(taxable_miles: Decimal, terms: TaxTerms) -> Decimal:
    if not terms.is_electric:
        return Decimal("0.00")
    if taxable_miles < ELECTRIC_SURCHARGE_THRESHOLD:
        return Decimal("0.00")
    return terms.electric_surcharge.quantize(CENT, rounding=ROUND_HALF_UP)


def calculate_road_use_tax(miles: JurisdictionMiles, terms: TaxTerms) -> Decimal:
    """Return tax owed for one jurisdiction for one filing period.

    Yard and ferry miles are ignored entirely. Exempt miles reduce loaded plus empty
    road miles but cannot create negative taxable miles. Fewer than 10 taxable miles
    produces no tax and no electric surcharge. For larger periods, tax is based on
    ``terms.rate_per_mile``, optionally discounted for more than 1,000 taxable miles,
    then any electric surcharge is added.
    """
    _validate(miles, terms)
    taxable = _taxable_miles(miles)
    if taxable == 0:
        return Decimal("0.00")
    return _base_tax(taxable, terms.rate_per_mile) + _surcharge(taxable, terms)

